pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The reference contract requires exactly 1 ether to lockInGuess
        // The buggy contract requires 0.5 ether instead
        // Setup: deploy already sent 1 ether, so c.balance = 1 ether
        // Now call lockInGuess with 1 ether on reference (will succeed because requirement is 1 ether)
        // On buggy, calling with 0.5 ether will succeed (because requirement is 0.5 ether)
        // After a call to lockInGuess, reference c.balance = 2 ether, buggy c.balance = 1.5 ether
        // We'll simulate both scenarios via vm.prank
        // But the test is a single concrete scenario: we are testing the contract as deployed
        // So we call lockInGuess with 1 ether (the value that passes in reference but would fail in buggy)
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        // This will succeed in reference (requires 1 ether) but revert in buggy (requires 0.5 ether)
        // We want the assertion to show divergence: 
        // reference: call succeeds -> c.balance increases by 1 ether
        // buggy: call reverts -> c.balance unchanged
        // So we check balance after
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(uint(1))));
        assertTrue(address(c).balance == 2 ether); // reference passes, buggy fails (buggy balance stays 1 ether because revert)
    }
}

