pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(this), 2 ether);

        // For the reference contract (msg.value == 1 ether), lockInGuess reverts with 0.5 ether
        // We'll just call lockInGuess with 0.5 ether and then settle to observe the difference
        // But since we only have one contract instance in the test, we test the behavior of the deployed contract
        // (which is either reference or buggy depending on src file). 
        // To witness divergence: call lockInGuess with 0.5 ether, then settle.
        // Reference: lockInGuess reverts -> settle also reverts (guesses[].block stays 0)
        // Buggy: lockInGuess succeeds with 0.5 ether -> if answer matches, transfer 2 ether

        // Step 1: Fund this contract (already done above)
        // Step 2: Call lockInGuess with 0.5 ether and a predictable guess
        bytes32 myGuess = keccak256("test");

        // Try lockInGuess — it might revert (reference) or succeed (buggy)
        bool lockOk;
        try c.lockInGuess{value: 0.5 ether}(myGuess) {
            lockOk = true;
        } catch {
            lockOk = false;
        }

        // Warp to future block so settle can work (in case lock succeeded)
        vm.roll(block.number + 2);

        // Now try settle
        bool settleOk;
        try c.settle() {
            settleOk = true;
        } catch {
            settleOk = false;
        }

        // For the reference: lockInGuess reverts (lockOk == false), so settle also reverts (settleOk == false)
        // For the buggy: lockInGuess succeeds (lockOk == true), and if answer matches guess, settle succeeds (settleOk == true)
        // Since we can't predict blockhash, answer may be 0 and settle won't transfer, but settle will execute without revert
        // Actually settle only reverts if block == 0 or block not passed, so on buggy lock succeeded -> settle doesn't revert
        // On reference lock reverted -> block == 0 -> settle reverts
        // So assert that lockOk is true and settleOk is true for buggy; false for reference
        // We just assert that lockOk == settleOk (both true on buggy, both false on reference)
        // But since we need one assertion the reference satisfies and bug breaks:
        // Reference: settleOk == false; Buggy: settleOk == true
        assertTrue(settleOk);
    }
}

