import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up the scenario:
        // 1. Deploying contract with 1 ether
        vm.deal(address(c), 2 ether);
        // 2. Fund a caller with 1 ether
        address caller = address(0x1234);
        vm.deal(caller, 1 ether);
        // 3. Warp to block 1, then move to block 2 after lockInGuess
        vm.roll(1);
        // 4. Caller calls lockInGuess with a specific hash
        bytes32 targetHash = keccak256(abi.encodePacked("test"));
        vm.prank(caller);
        (bool ok) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", targetHash));
        // lockInGuess must succeed
        require(ok, "lockInGuess failed");
        // 5. Move to block 3 so block.number > guesses[caller].block (which is now 2)
        vm.roll(3);
        // 6. The blockhash of block 2 will be zero in this test environment (or unknown), but we pick a scenario where it is non-zero by using a fixed blockhash expectation.
        // Actually to guarantee blockhash(2) is known, we must be on chain with block.number <= 256. Here block.number = 3, blockhash(2) is known but may be zero unless we set it. In Foundry, blockhash of previous blocks is zero by default. To make the test deterministic, we use a block where blockhash is known to be zero, so the correct contract will also not transfer. To create a divergence, we avoid blockhash dependency by noting that the bug is the missing assignment: the mutant never sets guess, so even if blockhash is non-zero, guess is bytes32(0) which may differ from answer. So we need a blockhash that is non-zero.
        // Use vm.etch to simulate? No, not allowed. Simpler: use blockhash(block.number - 1) in the test contract? That's not accessible. So we choose a scenario where the guess is set to the blockhash of the next block, then settle after. In Foundry default, blockhash(block.number - 1) is zero for blocks before the current unless we use vm.roll and vm.warp. Actually vm.roll with block.number from 0? Not allowed. Standard approach: after vm.roll(1), blockhash(0) is zero, so we cannot rely. 
        // Alternative: use a concrete scenario where the reference transfers and the bug does not, even with blockhash zero? The reference requires answer != 0. So if blockhash is zero, neither transfers. To create divergence, we need a non-zero blockhash. In Foundry, we can precompute: blockhash(1) after vm.roll(2) is keccak256(abi.encodePacked(block.chainid, 1, block.gaslimit, block.coinbase, block.timestamp, block.difficulty, block.prevrandao...))? It's not easily overridable. So we cheat: we do not rely on blockhash non-zero. Instead, we use the fact that the mutant never sets guess, so if the answer (blockhash) equals the hash passed, the reference transfers, but the mutant will not because guess is zero. So we must make blockhash(guesses[caller].block) equal to the hash we passed. We can set that by vm.roll to a block number where blockhash is known to be our targetHash? Not possible. Thus, we rely on blockhash being zero: both fail. Not divergent.
        // Cleaner divergence: the reference sets guesses[caller].guess to hash, the mutant does not. So a public getter guesses(caller).guess will return hash in reference and bytes32(0) in mutant. That's observable.
        // So: after lockInGuess, read the guesses mapping via auto-generated getter.
        (uint256 blockNum, bytes32 guess) = c.guesses(caller);
        // In reference, guess == targetHash; in mutant, guess == bytes32(0).
        // Use assertEq(guess, targetHash) which passes on reference, fails on mutant.
        assertEq(guess, targetHash);
    }
}

